"""
Export-stage integrity.

The manifest is generated from the database and is therefore always right. The
*directory tree* is generated by copying files, and until this file existed
nothing checked that the two agreed. They did not: `images/` only ever grew.

That matters because the folder layout is the artefact a training script
actually walks. `torchvision.datasets.ImageFolder` does not read the manifest;
it reads directories. A stale file under `images/train/cat/` is training data
as far as it is concerned, whatever the manifest says.
"""

from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path
from uuid import uuid4

import pytest

from src.pipeline import export


@pytest.fixture
def store(tmp_path: Path) -> Path:
    """A content-addressed image store holding four tiny files."""
    images = tmp_path / "store"
    images.mkdir()
    for sha in ("a" * 64, "b" * 64, "c" * 64, "d" * 64):
        (images / f"{sha}.jpg").write_bytes(b"\xff\xd8\xff" + sha.encode()[:32])
    return images


def _row(sha: str, split: str, store: Path, class_label: str = "cat") -> dict:
    return {
        "sha256": sha,
        "class_label": class_label,
        "split": split,
        "source": "openverse",
        "source_id": sha[:8],
        "source_url": "https://example.org/p",
        "origin_url": "https://example.org/p.jpg",
        "license": "CC-BY-4.0",
        "license_url": "https://creativecommons.org/licenses/by/4.0/",
        "attribution": "Someone",
        "storage_path": str(store / f"{sha}.jpg"),
        "format": "JPEG",
        "width": 100,
        "height": 100,
        "file_size_bytes": 35,
        "retrieved_at": datetime.now(timezone.utc),
    }


def _export(rows, out: Path):
    return export.run(rows=rows, output_dir=out, run_id=uuid4())


def test_an_image_that_changes_split_does_not_remain_in_the_old_one(store, tmp_path):
    """
    The leakage regression.

    Splitting runs over the whole stored dataset, so an image moving from train
    to val as the dataset grows is normal and expected. Leaving the previous
    copy behind is not: the same photograph then sits in both directories, and
    every loader that walks the tree trains on its own validation set.
    """
    out = tmp_path / "output"
    rows = [_row("a" * 64, "train", store)]
    _export(rows, out)
    assert (out / "images/train/cat" / f"{'a' * 64}.jpg").exists()

    moved = [_row("a" * 64, "val", store)]
    summary = _export(moved, out)

    assert (out / "images/val/cat" / f"{'a' * 64}.jpg").exists()
    assert not (out / "images/train/cat" / f"{'a' * 64}.jpg").exists(), (
        "the image is now in val; leaving the train copy is train/val leakage"
    )
    assert summary["images_pruned"] == 1


def test_no_sha_appears_under_two_splits_after_a_reshuffle(store, tmp_path):
    """
    The property stated directly, over a set rather than one file: whatever the
    tree contains, no checksum may appear on both sides of the boundary.
    """
    out = tmp_path / "output"
    shas = ["a" * 64, "b" * 64, "c" * 64, "d" * 64]
    _export([_row(s, "train", store) for s in shas], out)
    # Every image swaps sides at once — the worst case of an ordinary reshuffle.
    _export([_row(s, "val", store) for s in shas], out)

    seen: dict[str, set[str]] = {}
    for path in (out / "images").rglob("*.jpg"):
        seen.setdefault(path.stem, set()).add(path.parent.parent.name)

    assert all(len(splits) == 1 for splits in seen.values()), seen


def test_an_image_dropped_from_the_dataset_is_removed_from_the_tree(store, tmp_path):
    """
    Trimmed at the class target, or marked a near-duplicate on a later run:
    either way the manifest stops claiming it, and the exported tree must stop
    shipping it. Otherwise the dataset on disk is quietly larger than the
    dataset described.
    """
    out = tmp_path / "output"
    _export([_row(s, "train", store) for s in ("a" * 64, "b" * 64)], out)
    summary = _export([_row("a" * 64, "train", store)], out)

    assert summary["images_pruned"] == 1
    remaining = {p.stem for p in (out / "images").rglob("*.jpg")}
    assert remaining == {"a" * 64}


def test_the_tree_matches_the_manifest_exactly(store, tmp_path):
    """
    The invariant both of the above are instances of: the set of files on disk
    and the set of paths in the manifest are the same set. Checked after a
    reshuffle, because that is when they diverged.
    """
    out = tmp_path / "output"
    _export([_row(s, "train", store) for s in ("a" * 64, "b" * 64, "c" * 64)], out)
    _export(
        [_row("a" * 64, "val", store), _row("b" * 64, "train", store)],
        out,
    )

    manifest = json.loads((out / "manifest.json").read_text(encoding="utf-8"))
    claimed = {entry["path"] for entry in manifest["images"]}
    on_disk = {
        str(p.relative_to(out)).replace("\\", "/") for p in (out / "images").rglob("*.jpg")
    }

    assert on_disk == claimed


def test_pruning_never_touches_the_committed_sample(store, tmp_path):
    """
    `sample_images/` is a sibling of `images/`, committed to the repository and
    not generated here. A prune that reached it would delete 24 files a
    reviewer is meant to be able to look at without running anything.
    """
    out = tmp_path / "output"
    sample = out / "sample_images" / "train" / "cat"
    sample.mkdir(parents=True)
    (sample / "keepme.jpg").write_bytes(b"\xff\xd8\xff")

    _export([_row("a" * 64, "train", store)], out)
    _export([_row("b" * 64, "val", store)], out)

    assert (sample / "keepme.jpg").exists()


def test_an_unchanged_dataset_prunes_nothing(store, tmp_path):
    """Re-running an identical export must be a no-op, not a delete-and-copy."""
    out = tmp_path / "output"
    rows = [_row(s, "train", store) for s in ("a" * 64, "b" * 64)]
    _export(rows, out)
    summary = _export(rows, out)

    assert summary["images_pruned"] == 0
    assert summary["images_copied"] == 2
